/**
 * DSH Script Manager Plugin - Script Tools
 * script_manage 按 action 拆分为独立单操作工具：
 *   script_list / script_get / script_create / script_update /
 *   script_delete / script_search，外加 script_run（执行）。
 */

import type { Context } from '@deepseek-ai/cordis';
import { defineTool } from '@deepseek-ai/dsh-tools';
import type { JsonValue } from '@deepseek-ai/dsh-tools';
import type { ContentBlock } from '@deepseek-ai/dsh-llm';
import type { ScriptStore } from './script-store.js';
import type { ScriptRunner } from './script-runner.js';
import type { HistoryStore } from './history-store.js';
import { formatScriptResult } from './format-script-result.js';

/** 工具参数（单操作工具各自的入参）。 */
interface ToolArgs {
  scriptId?: string;
  script?: Record<string, unknown>;
  query?: string;
  tags?: string[];
  limit?: number;
  offset?: number;
  includeSnapshot?: boolean;
  timeoutMs?: number;
}

/** 通用 JSON 输出渲染：schema 字面量驱动 defineTool 的 O=json 推断；render 以 text 块承载 JSON
 * （宿主 LLM adapter 仅把 text 块拼进模型可见内容，其余块类型会被丢弃，故不能用自定义 json 块）。 */
function jsonOutput(): { schema: { type: 'json' }; render: (args: unknown, value: JsonValue) => ContentBlock[] } {
  return {
    schema: { type: 'json' },
    render: (_a: unknown, v: JsonValue) => [{ type: 'text', text: jsonToText(v) }],
  };
}
/** JsonValue → 文本（undefined 兜底空串）。 */
function jsonToText(v: JsonValue): string {
  try {
    const text = JSON.stringify(v, null, 2);
    return text === undefined ? '' : text;
  } catch {
    return String(v);
  }
}

export function registerScriptTools(
  ctx: Context,
  store: ScriptStore,
  runner: ScriptRunner,
  onChanged?: () => Promise<void> | void,
  history?: HistoryStore,
): () => void {
  const disposers: (() => void)[] = [];

  // script 对象的逐字段 schema（模型可见的 JSON Schema 结构）
  const SCRIPT_FIELDS = {
    id: { type: 'string', description: 'Unique script id (lowercase letters/digits/hyphens, file name base).' },
    name: { type: 'string', description: 'Display name of the script.' },
    description: { type: 'string', description: 'Script purpose note sent to the model.' },
    version: { type: 'string', description: 'Version string (defaults to 0.1.0).' },
    author: { type: 'string', description: 'Author name (optional).' },
    tags: { type: 'array', items: { type: 'string' }, description: 'Optional tags.' },
    code: { type: 'string', description: 'The TypeScript async function body; may return a value; runs with tools.* bindings (tools.read, tools.bash, ...) available.' },
    registerAsTool: { type: 'boolean', description: 'When true, register the script as a no-argument agent tool named by toolName.' },
    toolName: { type: 'string', description: 'Dynamic tool name when registerAsTool is true; must match ^[a-z_][a-z0-9_]*$; defaults to script_<id>.' },
    timeoutMs: { type: 'number', description: 'Optional per-run timeout budget in milliseconds (positive integer). Defaults to the plugin maxExecutionTime config (0 = unlimited); a script_run({ timeoutMs }) call overrides it for one run.' },
    parameters: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          name: { type: 'string', description: 'Parameter name - a valid identifier ([A-Za-z_][A-Za-z0-9_]*); the script reads it as params.<name>.' },
          type: { type: 'string', enum: ['string', 'number', 'boolean'], description: 'Value type (default string).' },
          label: { type: 'string', description: 'Display label (defaults to name).' },
          description: { type: 'string', description: 'Short description shown to callers.' },
          required: { type: 'boolean', description: 'Required parameters have no default and must be provided at run time.' },
          default: { type: 'json', description: 'Default value for optional parameters (must match type; JSON-scalar string/number/boolean).' },
        },
      },
      description: 'Parameter declarations (optional). Rule: required=true must NOT declare a default; required=false MUST declare a default matching type. Optional parameters run with defaults when omitted.',
    },
    expectedOutcome: { type: 'string', description: 'Execution contract (optional, multi-line): the outcome the script is intended to achieve once finished. Surfaced with the run result so the agent can check whether the intended behavior was reached.' },
    successCriteria: { type: 'string', description: 'Execution contract (optional, multi-line): how to verify the script reached its intended outcome - concrete checkpoints (artifacts, exit codes, output patterns, return fields). Surfaced with the run result.' },
    failureGuidance: { type: 'string', description: 'Execution contract (optional, multi-line): how the agent should intervene when the outcome is not as expected or the run failed - inputs to adjust, manual steps, or updating the script then rerunning. Surfaced with the run result.' },
  } as const;

  const CREATE_SCRIPT_SCHEMA = {
    type: 'object',
    additionalProperties: false,
    properties: {
      ...SCRIPT_FIELDS,
      id: { ...SCRIPT_FIELDS.id, required: true as const },
      name: { ...SCRIPT_FIELDS.name, required: true as const },
      code: { ...SCRIPT_FIELDS.code, required: true as const },
    },
  };
  // update 是部分补丁：字段均可选
  const UPDATE_SCRIPT_SCHEMA = { type: 'object', additionalProperties: false, properties: SCRIPT_FIELDS };

  const definitions: {
    name: string;
    description: string;
    parameters: Record<string, unknown>;
    execute: (args: ToolArgs) => Promise<unknown>;
  }[] = [
    {
      name: 'script_list',
      description: 'List custom script summaries (id/name/description/version/tags/metadata), optionally filtered by tags or limited.',
      parameters: {
        tags: { type: 'array', items: { type: 'string' }, description: 'Optional tag filter.' },
        limit: { type: 'number', description: 'Optional maximum number of results.' },
      },
      execute: (args: ToolArgs) => store.list({ tags: args.tags, limit: args.limit }),
    },
    {
      name: 'script_get',
      description: 'Fetch the full definition of one custom script by id (includes its code).',
      parameters: {
        scriptId: { type: 'string', required: true, description: 'Unique script id (lowercase letters/digits/hyphens), e.g. hello-world.' },
      },
      execute: async (args: ToolArgs) => {
        if (!args.scriptId) throw new Error('scriptId required');
        const script = await store.get(args.scriptId);
        if (!script) throw new Error('Script not found: ' + args.scriptId);
        return script;
      },
    },
    {
      name: 'script_create',
      description: 'Create a new custom script. The script body runs in an async TypeScript context with tools.* bindings (e.g. tools.read, tools.bash) available.',
      parameters: {
        script: {
          type: 'object',
          required: true,
          additionalProperties: false,
          properties: CREATE_SCRIPT_SCHEMA.properties,
          description: 'Script definition object; see properties for field formats. Required: id, name, code.',
        },
      },
      execute: async (args: ToolArgs) => {
        if (!args.script) throw new Error('script required');
        const created = await store.create(args.script as any, { source: 'tool' });
        if (onChanged) await onChanged();
        return created;
      },
    },
    {
      name: 'script_update',
      description: 'Update an existing custom script by id (partial patch; changing id renames the script file).',
      parameters: {
        scriptId: { type: 'string', required: true, description: 'Unique script id to update, e.g. hello-world.' },
        script: {
          type: 'object',
          required: true,
          additionalProperties: false,
          properties: UPDATE_SCRIPT_SCHEMA.properties,
          description: 'Partial patch object; accepted fields are the same as script_create (id, name, description, version, author, tags, code, registerAsTool, toolName). Unset fields keep current values.',
        },
      },
      execute: async (args: ToolArgs) => {
        if (!args.scriptId) throw new Error('scriptId required');
        const updated = await store.update(args.scriptId, args.script || {}, { source: 'tool' });
        if (onChanged) await onChanged();
        return updated;
      },
    },
    {
      name: 'script_delete',
      description: 'Delete a custom script by id (removes its file and any registered dynamic tool).',
      parameters: {
        scriptId: { type: 'string', required: true, description: 'Unique script id to delete.' },
      },
      execute: async (args: ToolArgs) => {
        if (!args.scriptId) throw new Error('scriptId required');
        const ok = await store.delete(args.scriptId, { source: 'tool' });
        if (onChanged) await onChanged();
        if (!ok) throw new Error('Script not found: ' + args.scriptId);
        return { success: true };
      },
    },
    {
      name: 'script_search',
      description: 'Search custom scripts by text matched against id/name/description, optionally filtered by tags.',
      parameters: {
        query: { type: 'string', required: true, description: 'Search text.' },
        tags: { type: 'array', items: { type: 'string' }, description: 'Optional tag filter.' },
      },
      execute: (args: ToolArgs) => store.search(args.query || '', { tags: args.tags }),
    },
    {
      name: 'script_change_history',
      description: 'Query the change history of custom scripts (create/update/rename with revision number, changed fields and optional full snapshot of each version). Useful to see what changed when and which definition revision a version had. Per-script storage keeps each script separate; deleting a script also deletes its history.',
      parameters: {
        scriptId: { type: 'string', description: 'Optional script id filter (omit to query across all scripts).' },
        limit: { type: 'number', description: 'Optional max entries (default 20, cap 100).' },
        offset: { type: 'number', description: 'Optional offset into newest-first results.' },
        includeSnapshot: { type: 'boolean', description: 'Include the full definition snapshot (with code) of each version. Default false to keep responses small.' },
      },
      execute: async (args: ToolArgs) => {
        if (!history) throw new Error('History is disabled (historyEnabled=false)');
        const limit = clampLimit(args.limit, 20, 100);
        return history.listChanges({
          scriptId: args.scriptId || undefined,
          limit,
          offset: args.offset,
          includeSnapshot: args.includeSnapshot === true,
        });
      },
    },
    {
      name: 'script_run_history',
      description: 'Query the execution history of custom scripts (timestamp, revision the script was at when executed, caller, params, success/error, duration, return summary). Useful to see when a script started failing and with which params, and which definition revision each run used.',
      parameters: {
        scriptId: { type: 'string', description: 'Optional script id filter (omit to query across all scripts).' },
        limit: { type: 'number', description: 'Optional max entries (default 20, cap 100).' },
        offset: { type: 'number', description: 'Optional offset into newest-first results.' },
      },
      execute: async (args: ToolArgs) => {
        if (!history) throw new Error('History is disabled (historyEnabled=false)');
        return history.listRuns({
          scriptId: args.scriptId || undefined,
          limit: clampLimit(args.limit, 20, 100),
          offset: args.offset,
        });
      },
    },
  ];

  for (const def of definitions) {
    disposers.push(ctx.tools.register(defineTool({
      name: def.name,
      description: def.description,
      parameters: def.parameters as any,
      output: jsonOutput(),
      // store/history 返回值均为可序列化 JSON（自 JSON 文件解析而来），此处经断言对齐 defineTool 的 json 输出契约
      async execute(args: any) { return def.execute(args as ToolArgs) as unknown as Promise<JsonValue>; },
    })));
  }

  disposers.push(ctx.tools.register(defineTool({
    name: 'script_run',
    description: 'Execute a registered custom script by its id. The script runs in an async TypeScript context with tools.* bindings (e.g. tools.read, tools.bash) available.',
    parameters: {
      scriptId: {
        type: 'string', required: true,
        description: 'The script id to execute (e.g. hello-world, project-info). Fetch available ids via script_list.',
      },
      timeoutMs: {
        type: 'number',
        description: 'Optional per-run timeout budget in milliseconds (positive integer). Overrides the script/plugin default for this run only. Omit for no override.',
      },
      params: {
        type: 'object',
        additionalProperties: true,
        description: 'Input parameters keyed by the script\'s declared parameter names (script_get/script_list expose the declarations). Required parameters must be provided; omitted optional parameters fall back to their defaults. Unknown keys are ignored but reported. Value types follow each parameter\'s declared type (string/number/boolean).',
      },
    },
    output: {
      schema: { type: 'json' },
      // 与 /script 命令共用 formatScriptResult，保证模型看到的输出完全一致
      render: (_a: unknown, v: unknown) => [{ type: 'text', text: formatScriptResult(v as Record<string, unknown>) }],
    },
    async execute(args: any, exec: any) {
      // 透传外层执行身份：内层 tools.* 子分发事件挂在本 script_run 调用之下，
      // Web GUI 据此把脚本内部调用渲染为 PTC 同款嵌套层级（rootCallId 需一致）。
      const result = await runner.run(args.scriptId, exec.signal, exec.agent, exec.token, args.timeoutMs, {
        callId: String(exec.callId),
        rootCallId: String(exec.rootCallId ?? exec.callId),
      }, args.params as Record<string, unknown> | undefined, 'script_run');
      return result as unknown as JsonValue;
    },
  })));

  return () => { for (const d of disposers) d(); };
}

/** 限制 limit 参数到合理区间（默认 defaultN，上限 cap）。 */
function clampLimit(value: unknown, defaultN: number, cap: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) return defaultN;
  return Math.min(Math.floor(value), cap);
}
